'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {applicationUuid as uuid} from '@/lib/opening-invoice-application';
import {sameCorrectionReview} from '@/lib/invoice-correction';
type Match={id:string;reservation:string;source:string};
type Request={id:string;scope:HandoffScope;batch:string;match:Match;invoice:string;reason:string;review:Record<string,unknown>};
export function validateMatchCorrection(p:Request,scope:HandoffScope,batch:string){const r=p?.review,m=r?.match as Record<string,unknown>,i=r?.replacement_invoice as Record<string,unknown>;if(!p||p.scope?.tenant!==scope.tenant||p.scope?.property!==scope.property||p.scope?.actor!==scope.actor||p.batch!==batch||!uuid(p.id)||!uuid(p.match?.id)||!uuid(p.match.reservation)||!uuid(p.invoice)||typeof p.reason!=='string'||p.reason.trim()!==p.reason||p.reason.length<4||p.reason.length>500||/[\x00-\x1f\x7f]/.test(p.reason)||!r||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.schema_version!==1||r.moves_money!==false||r.creates_opening!==false||r.ready_to_post!==false||!m||m.id!==p.match.id||m.reservation_id!==p.match.reservation||!Number.isSafeInteger(m.version)||Number(m.version)<0||!i||i.invoice_id!==p.invoice||i.reservation_id!==p.match.reservation)throw Error('Saved invoice match review does not match.');if(m.tenant_id!==scope.tenant||m.property_id!==scope.property||!uuid(m.invoice_id)||m.invoice_id===p.invoice||i.tenant_id!==scope.tenant||i.property_id!==scope.property||i.actor_id!==scope.actor||!Number.isSafeInteger(m.amount_minor)||Number(m.amount_minor)<=0||typeof r.replacement_unmatched_minor!=='string'||!/^(0|[1-9][0-9]{0,11})$/.test(r.replacement_unmatched_minor)||BigInt(r.replacement_unmatched_minor)<BigInt(Number(m.amount_minor)))throw Error('Invoice match source or capacity is invalid.');}
function receipt(v:unknown,p:Request){const r=v as Record<string,unknown>,m=p.review.match as Record<string,unknown>;if(!r||r.request_id!==p.id||r.match_id!==p.match.id||r.version!==Number(m.version)+1||typeof r.replayed!=='boolean'||r.moves_money!==false)throw Error('Invoice match receipt does not match.');}
export function FinancialMatchCorrection({scope,batch,matches,onCompleted}:{scope:HandoffScope;batch:string;matches:Match[];onCompleted:()=>void}){
 const [pending,setPending]=useState<Request|null>(null),[review,setReview]=useState<Request|null>(null),[match,setMatch]=useState(''),[invoice,setInvoice]=useState(''),[reason,setReason]=useState(''),[invoices,setInvoices]=useState<{id:string;number:string}[]>([]),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[busy,setBusy]=useState(false),[ready,setReady]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const key=['irp.migration.rematch.v1',scope.tenant,scope.property,scope.actor,batch].join(':'),alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw);validateMatchCorrection(p,scope,batch);setPending(p)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore correction.')}return()=>{alive.current=false}},[key]);
 function changed(){setReview(null);setConfirmed(false)}
 async function run(action:'load'|'review'|'post'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{const identify=async()=>{const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.')};await identify();const base={p_tenant:scope.tenant,p_property:scope.property},selected=matches.find(m=>m.id===match);
   if(action==='load'){if(!selected)throw Error('Choose a source match.');const r=await hotelRpc<Record<string,unknown>>('reservation_invoices',{...base,p_reservation:selected.reservation});if(r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.reservation_id!==selected.reservation||r.complete!==true||!Array.isArray(r.invoices))throw Error('Invoice list does not match.');const values=r.invoices.map(i=>{if(!uuid(i.invoice_id)||typeof i.number!=='string')throw Error('Invalid invoice list.');return {id:i.invoice_id,number:i.number}});await identify();if(alive.current)setInvoices(values);return}
   if(action==='review'){if(!selected||!invoices.some(i=>i.id===invoice))throw Error('Choose the match and replacement invoice.');const r=await hotelRpc<Record<string,unknown>>('preview_migration_invoice_rematch',{...base,p_match:match,p_invoice:invoice});const p={id:crypto.randomUUID(),scope,batch,match:selected,invoice,reason:reason.trim(),review:r};validateMatchCorrection(p,scope,batch);await identify();if(alive.current){setReview(p);setConfirmed(false)}return}
   const p=pending??review;if(!p)throw Error('Review the correction first.');validateMatchCorrection(p,scope,batch);let complete=false,cancelled=false;
   if(action==='post'){if(!confirmed)throw Error('Confirm the correction.');if(!pending){if(sessionStorage.getItem(key))throw Error('Recover the saved request first.');sessionStorage.setItem(key,JSON.stringify(p));setPending(p)}receipt(await hotelRpc('rematch_migration_invoice',{...base,p_request:p.id,p_review:p.review,p_reason:p.reason}),p);complete=true}
   else{if(action==='cancel'){if(!cancelConfirmed)throw Error('Confirm request cancellation.');await hotelRpc('cancel_migration_invoice_rematch',{...base,p_request:p.id,p_confirmed:true})}const s=await hotelRpc<Record<string,unknown>>('migration_invoice_rematch_status',{...base,p_request:p.id});if(s.schema_version!==1||s.tenant_id!==scope.tenant||s.property_id!==scope.property||s.actor_id!==scope.actor||s.request_id!==p.id||typeof s.found!=='boolean'||typeof s.cancelled!=='boolean'||s.found&&s.cancelled||!s.found&&s.result!==null)throw Error('Recovery status does not match.');if(s.found){if(!sameCorrectionReview(s.review,p.review))throw Error('Recovered review changed.');receipt(s.result,p);complete=true}cancelled=s.cancelled===true}
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setReview(null);setConfirmed(false);setCancelConfirmed(false);setMessage(complete?'Invoice match corrected.':'Invoice match request cancelled.');if(complete)onCompleted()}else setMessage('No correction found. Retry or cancel the saved request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to correct invoice match.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 const selected=pending??review;
 return <section aria-label="Correct migration invoice match"><h3>Correct an invoice match</h3><p>Choose another invoice for the same stay. This preserves the original import and does not change invoice balances.</p><fieldset disabled={busy||!ready||!!pending}><label>Source match<select value={match} onChange={e=>{setMatch(e.target.value);setInvoice('');setInvoices([]);changed()}}><option value="">Choose source</option>{matches.map(m=><option key={m.id} value={m.id}>{m.source}</option>)}</select></label><button type="button" onClick={()=>void run('load')}>Load replacement invoices</button><label>Replacement invoice<select value={invoice} onChange={e=>{setInvoice(e.target.value);changed()}}><option value="">Choose invoice</option>{invoices.map(i=><option key={i.id} value={i.id}>Invoice {i.number}</option>)}</select></label><label>Match correction reason<input value={reason} maxLength={500} onChange={e=>{setReason(e.target.value);changed()}}/></label><button type="button" onClick={()=>void run('review')}>Review match correction</button></fieldset>
 {selected&&<><p role="status">Change invoice {String((selected.review.match as Record<string,unknown>).invoice_id)} to {selected.invoice}. Reason: {selected.reason}</p><label><input type="checkbox" disabled={busy} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I confirm the replacement invoice match</label><button type="button" disabled={busy||!confirmed} onClick={()=>void run('post')}>{pending?'Retry match correction':'Record match correction'}</button></>}{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check match correction outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if match was not corrected</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel match correction request</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
